using System.Text.Json;
using YoshiWorkshop;
string root=Path.GetFullPath(args[0]);if(!root.Contains("validation",StringComparison.OrdinalIgnoreCase))throw new Exception("Use an isolated validation root.");
string fixture=Path.GetFullPath(args[1]);var runner=new SpecialContentRunner(root);var rom=new VanillaRom(runner.OriginalRom);var store=new ProjectStore(Path.Combine(root,"content"));
var one=JsonSerializer.Deserialize<LevelProject>(File.ReadAllText(fixture),ProjectStore.Json)!;one.Id=Guid.NewGuid().ToString("N");one.Name="Victoire automatique 1";store.Save(one);var two=store.Duplicate(one);two.Name="Victoire automatique 2";store.Save(two);
var game=new CustomGame{Name="Validation native de deux victoires",LevelIds=[one.Id,two.Id]};store.Save(game);var session=new CustomGameSession(root,runner,rom);using var done=new ManualResetEventSlim();string? error=null;int launches=0;
session.DiagnosticArguments=i=>{launches++;string input=Path.Combine(root,"build",$"chain-{game.Id}-{i}.inputs");File.WriteAllText(input,i>0?"1 2 0 0 0\n":"600 608 1000 0 0\n1200 1208 1000 0 0\n1800 1808 8000 0 0\n"+string.Join("",Enumerable.Range(0,20).Select(n=>$"{2550+n*110} {2558+n*110} 4000 0 0\n")));return (i==0?new[]{"--workshop-auto-color","0"}:Array.Empty<string>()).Concat(new[]{"--workshop-input",input,"--workshop-test-tally","--workshop-end-vi","6000","--workshop-background-test"});};
session.Changed+=()=>{var s=session.State!;Console.WriteLine($"phase={s.Phase} index={s.Index} pid={s.ProcessId}");if(s.Phase=="completed")done.Set();};
session.Error+=e=>{error=e;done.Set();};session.Start(game,store);bool timed=false;var clock=System.Diagnostics.Stopwatch.StartNew();DateTime? idle=null;while(clock.Elapsed.TotalSeconds<280){if(done.Wait(200)){timed=true;break;}if(session.State is {Phase:"paused",ProcessId:0}){idle??=DateTime.UtcNow;if((DateTime.UtcNow-idle.Value).TotalSeconds>3){error="Native exit without victory";break;}}else idle=null;}if(!timed && runner.Running is {HasExited:false} p)p.Kill();var reloaded=new CustomGameSession(root,runner,rom).Read(game.Id);bool reloadOk=reloaded is {Phase:"completed",Index:2} && reloaded.Results.Count==2;var report=new{finished=timed,error,launches,persistedReloadVerified=reloadOk,fixture="29 seeded fruits plus real native fruit-consumption callback",automaticContinuationWithoutScriptedInput=true,state=session.State,profile=Path.GetDirectoryName(session.SessionPath(game.Id))};File.WriteAllText(Path.Combine(root,"build/editor-0140/native-chain.json"),JsonSerializer.Serialize(report,ProjectStore.Json));if(!timed || error!=null || session.State?.Index!=2 || launches!=2 || !reloadOk)throw new Exception("Native chain failed: "+error);Console.WriteLine("Two real native victories chained successfully.");
